shellCommands.command:
node -e '
const fs=require("fs"),path=require("path");
const base="/workspace/.next/server/app";
function walk(d){let r=[];for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())r=r.concat(walk(p));else r.push(p)}return r}
const files=walk(base);
const ppr=files.filter(f=>f.includes("index")||f.endsWith(".html")||f.includes("postponed")||f.includes(".rsc"));
console.log("PPR-relevant files under .next/server/app:");
ppr.forEach(f=>console.log(" ",f.replace("/workspace/.next/server/app/",""),fs.statSync(f).size+"B"));
const manifest=JSON.parse(fs.readFileSync("/workspace/.next/server/app/index.js.manifest.json","utf8").length?fs.readFileSync("/workspace/.next/server/app/index.js.manifest.json","utf8"):"{}");
' 2>&1 | head -40
echo "--- prerender-manifest ---"
node -e 'const fs=require("fs");const j=JSON.parse(fs.readFileSync("/workspace/.next/prerender-manifest.json","utf8"));console.log("routes:",Object.keys(j.routes));console.log("preview:",JSON.stringify(j.preview).slice(0,120))' 2>&1 | head

node -e '
const fs=require("fs");
const html=fs.readFileSync("/workspace/.next/server/app/index.html","utf8");
const strip=s=>s.replace(/<template[^>]*>[\s\S]*?<\/template>/g,"[TEMPLATE]").replace(/<script[\s\S]*?<\/script>/g,"[SCRIPT]").replace(/<style[\s\S]*?<\/style>/g,"[STYLE]");
const body=html.match(/<body[^>]*>([\s\S]*?)<\/body>/);
console.log("=== Static shell body (tags stripped) ===");
console.log(body?strip(body[1]).replace(/\s+/g," ").trim().slice(0,600):"(no body)"));
console.log();
console.log("contains <h1>Dashboard</h1>?", html.includes("Dashboard"));
console.log("contains skeleton fallbacks?", html.includes("skeleton"));
console.log("contains CardStatsSection real data?", /totalRevenue|Total Revenue/.test(html) && !html.includes("skeleton"));
'

node --input-type=module -e '
import fs from "node:fs";
const html = fs.readFileSync("/workspace/.next/server/app/index.html","utf8");
const body = html.match(/<body[^>]*>([\s\S]*?)<\/body>/)[1]
  .replace(/<template[^>]*>[\s\S]*?<\/template>/g,"[TEMPLATE]")
  .replace(/<script[\s\S]*?<\/script>/g,"")
  .replace(/<style[\s\S]*?<\/style>/g,"")
  .replace(/\s+/g," ").trim();
console.log("=== Static shell body ===");
console.log(body.slice(0,700));
console.log();
console.log("h1 Dashboard in shell:", html.includes("Dashboard"));
console.log("skeleton fallbacks in shell:", html.includes("skeleton"));
console.log("real revenue numbers in shell:", /Total Revenue/.test(html));
'

node --input-type=module -e '
import fs from "node:fs";
const html = fs.readFileSync("/workspace/.next/server/app/index.html","utf8");
const meta = fs.readFileSync("/workspace/.next/server/app/index.meta","utf8");
